'use client';

import * as React from 'react';

// @interlace/reflection-card v1.1.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/reflection-card
// What changed since: https://ds.interlace.tools/c/reflection-card#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — ReflectionCard
 *
 * A quiet minute in a loud room: one prompt ("What surprised you today?"),
 * a field, and a promise that the answer is yours. It is private by
 * default; when the session allows it, the writer can choose to share it
 * with the room without their name, and only then is it checked like any
 * other room text (no links, no contact details, the blocklist). Saving
 * keeps the words in the card; where they are stored (this device, an
 * account) is the app's choice, and `privacy` says so in its own words.
 *
 * ## Anatomy
 *
 *   ReflectionCard                 (form — data-slot="reflection-card", data-state=writing|saved)
 *     ├─ div                       (data-slot="reflection-card-meta": e.g. "1 of 3", optional)
 *     ├─ label                     (data-slot="reflection-card-prompt": names the field)
 *     ├─ Textarea                  (data-slot="reflection-card-field": described by privacy + count)
 *     ├─ p                         (data-slot="reflection-card-privacy": "Only you see this.")
 *     ├─ label + Checkbox          (data-slot="reflection-card-share", when `shareable`)
 *     ├─ Button                    (data-slot="reflection-card-save")
 *     └─ p aria-live               (data-slot="reflection-card-message": saved, shared, or why not)
 *
 * ## Motion
 *
 * None beyond the controls' own. A reflection is not a reveal.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `form` props                                         |
 * | R6   | data-slot per part        | reflection-card / -meta / -prompt / -field / -privacy / -share / -save / -message |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R9   | Controlled + uncontrolled | `value` / `defaultValue` / `onChange` / `onSave`     |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R26  | A11y                      | labelled field; privacy and count describe it; outcome announced |
 */

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import { Textarea } from '@/components/ui/textarea';
import { checkText, visibleLength, type TextRefusal } from '@/components/ui/games/text-safety-model';

export const MIN_VIEWPORT = 320 as const;

interface ReflectionCardLabels {
  /** @default 'Only you see this.' */
  privacy?: string;
  /** @default 'Share it with the room, without my name' */
  share?: string;
  /** @default 'Save' */
  save?: string;
  /** @default 'Saved.' */
  saved?: string;
  /** @default 'Saved, and shared without your name.' */
  shared?: string;
  /** @default (n) => `${n} characters left` */
  left?: (remaining: number) => string;
  /** Why a shared reflection was not sent. It is still saved. */
  refused?: Partial<Record<TextRefusal, string>>;
}

type ReflectionCardProps = Omit<React.ComponentProps<'form'>, 'children' | 'onChange' | 'defaultValue' | 'onSubmit'> & {
  prompt: React.ReactNode;
  /** Above the prompt, e.g. "1 of 3". */
  meta?: React.ReactNode;
  value?: string;
  defaultValue?: string;
  onChange?: (text: string) => void;
  /** Called on save with the text and whether it is shared. A shared text has passed the room's checks. */
  onSave?: (text: string, options: { shared: boolean }) => void;
  /** Offer to share it with the room, without a name. @default false */
  shareable?: boolean;
  /** Words the room refuses, for a shared reflection. */
  blocklist?: readonly string[];
  /** @default 500 */
  maxLength?: number;
  /** @default 4 */
  rows?: number;
  placeholder?: string;
  labels?: ReflectionCardLabels;
};

const REFUSED: Record<TextRefusal, string> = {
  empty: 'Write something first.',
  'too-long': 'Saved. It is too long to share; try a shorter version.',
  'too-many-words': 'Saved. It is too long to share; try a shorter version.',
  link: 'Saved, not shared: links cannot be shared with the room.',
  contact: 'Saved, not shared: email addresses and phone numbers cannot be shared.',
  blocked: 'Saved, not shared: try other words to share it.',
};

type Status = { kind: 'writing' } | { kind: 'saved'; shared: boolean } | { kind: 'refused'; reason: TextRefusal };

function ReflectionCard({
  prompt,
  meta,
  value: valueProp,
  defaultValue = '',
  onChange,
  onSave,
  shareable = false,
  blocklist,
  maxLength = 500,
  rows = 4,
  placeholder,
  labels,
  className,
  ...props
}: ReflectionCardProps) {
  const [own, setOwn] = React.useState(defaultValue);
  const text = valueProp ?? own;
  const [share, setShare] = React.useState(false);
  const [status, setStatus] = React.useState<Status>({ kind: 'writing' });
  const fieldId = React.useId();
  const privacyId = React.useId();
  const countId = React.useId();
  const remaining = maxLength - visibleLength(text);

  const submit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const trimmed = text.trim();
    if (!trimmed) {
      setStatus({ kind: 'refused', reason: 'empty' });
      return;
    }
    if (share) {
      const check = checkText(trimmed, { maxLength, blocklist });
      if (!check.ok) {
        // A private reflection is never refused: it is saved, just not shared.
        onSave?.(trimmed, { shared: false });
        setStatus({ kind: 'refused', reason: check.reason });
        return;
      }
      onSave?.(check.text, { shared: true });
      setStatus({ kind: 'saved', shared: true });
      return;
    }
    onSave?.(trimmed, { shared: false });
    setStatus({ kind: 'saved', shared: false });
  };

  const message =
    status.kind === 'saved'
      ? status.shared
        ? (labels?.shared ?? 'Saved, and shared without your name.')
        : (labels?.saved ?? 'Saved.')
      : status.kind === 'refused'
        ? (labels?.refused?.[status.reason] ?? REFUSED[status.reason])
        : '';

  return (
    <form
      data-slot="reflection-card"
      data-state={status.kind === 'saved' ? 'saved' : 'writing'}
      data-min-viewport={String(MIN_VIEWPORT)}
      noValidate
      onSubmit={submit}
      className={cn('bg-card grid max-w-144 gap-3 rounded-xl border p-5', className)}
      {...props}
    >
      {meta ? (
        <div data-slot="reflection-card-meta" className="text-muted-foreground text-sm font-medium">
          {meta}
        </div>
      ) : null}
      <label
        htmlFor={fieldId}
        data-slot="reflection-card-prompt"
        className="font-heading text-lg font-semibold text-balance"
      >
        {prompt}
      </label>
      <Textarea
        id={fieldId}
        data-slot="reflection-card-field"
        value={text}
        rows={rows}
        placeholder={placeholder}
        aria-describedby={`${privacyId} ${countId}`}
        aria-invalid={status.kind === 'refused' && status.reason === 'empty' ? true : undefined}
        onChange={(e) => {
          if (valueProp === undefined) setOwn(e.target.value);
          onChange?.(e.target.value);
          if (status.kind !== 'writing') setStatus({ kind: 'writing' });
        }}
      />
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1">
        <p id={privacyId} data-slot="reflection-card-privacy" className="text-muted-foreground text-sm">
          {labels?.privacy ?? 'Only you see this.'}
        </p>
        <span
          id={countId}
          className={cn('text-xs tabular-nums', remaining < 0 ? 'text-destructive' : 'text-muted-foreground')}
        >
          {(labels?.left ?? ((n: number) => `${n} characters left`))(remaining)}
        </span>
      </div>
      {shareable ? (
        <label data-slot="reflection-card-share" className="flex items-start gap-3 text-sm">
          <Checkbox
            checked={share}
            onCheckedChange={(v) => {
              setShare(v === true);
              if (status.kind !== 'writing') setStatus({ kind: 'writing' });
            }}
            className="mt-0.5"
          />
          <span>{labels?.share ?? 'Share it with the room, without my name'}</span>
        </label>
      ) : null}
      <div className="flex flex-wrap items-center gap-3">
        <Button data-slot="reflection-card-save" type="submit">
          {labels?.save ?? 'Save'}
        </Button>
        <p
          data-slot="reflection-card-message"
          aria-live="polite"
          className={cn('text-sm', status.kind === 'refused' ? 'text-destructive' : 'text-muted-foreground')}
        >
          {message}
        </p>
      </div>
    </form>
  );
}
ReflectionCard.displayName = 'ReflectionCard';

export { ReflectionCard };
export type { ReflectionCardProps, ReflectionCardLabels };

export type TextRefusal = 'empty' | 'too-long' | 'too-many-words' | 'link' | 'contact' | 'blocked';

export interface TextRules {
  /** The most characters, as the reader counts them. @default 200 */
  maxLength?: number;
  /** The most words. @default Infinity */
  maxWords?: number;
  /** Words the room refuses. Matched whole, after `foldText`. */
  blocklist?: readonly string[];
  /** Let links through. @default false */
  allowLinks?: boolean;
  /** Let email addresses and phone numbers through. @default false */
  allowContact?: boolean;
}

export type TextCheck = { ok: true; text: string } | { ok: false; reason: TextRefusal };

const SWAPS: Record<string, string> = { '0': 'o', '1': 'i', '3': 'e', '4': 'a', '5': 's', '7': 't', '@': 'a', $: 's' };

/** Trims, collapses runs of white space and applies Unicode NFC, so the same word typed twice is the same string. */
export function tidyText(input: string): string {
  return input.normalize('NFC').replace(/\s+/gu, ' ').trim();
}

/** How many characters a reader sees (grapheme clusters, so an emoji or a letter with marks counts once). */
export function visibleLength(text: string): number {
  if (typeof Intl !== 'undefined' && 'Segmenter' in Intl) {
    let n = 0;
    for (const _ of new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text)) n++;
    return n;
  }
  return Array.from(text).length;
}

/** Splits into words on white space. */
export function wordsOf(text: string): string[] {
  const t = tidyText(text);
  return t ? t.split(' ') : [];
}

/**
 * The form used for matching, never for showing: lowercase, no accents or
 * combining marks (Latin accents, Hebrew points, Arabic short vowels), the
 * common letter swaps folded, and spelled-out letters joined.
 */
export function foldText(input: string): string {
  const base = input
    .normalize('NFKD')
    .replace(/\p{M}+/gu, '')
    .toLowerCase()
    .replace(/[013457@$]/g, (c) => SWAPS[c] as string);
  // "b a d", "b.a.d", "b-a-d" → "bad": three or more single letters in a row.
  const joined = base.replace(
    /(?<![\p{L}\p{N}])\p{L}(?:[\s.\-_*]+\p{L})(?:[\s.\-_*]+\p{L})+(?![\p{L}\p{N}])/gu,
    (run) => run.replace(/[\s.\-_*]+/g, ''),
  );
  return joined
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/gu, ' ')
    .trim();
}

const LINK =
  /(?:https?:\/\/|www\.)\S+|\b[\p{L}\p{N}-]+\.(?:com|net|org|io|co|me|ly|gg|app|dev|info|xyz|tv|link|site|online)\b/iu;
// Matched per word and anchored, with classes that cannot overlap, so a long
// run of one character costs linear time, not quadratic.
const EMAIL_WORD = /^[^@]+@[^@.]+(?:\.[^@.]+)+$/u;
const hasEmail = (text: string) => text.split(' ').some((word) => EMAIL_WORD.test(word));
// Seven or more digits, allowing the usual separators (spaces, dots,
// dashes, brackets, a leading plus) between them. A single pass, so no input
// can make it slow.
const PHONE_SEPARATORS = new Set([' ', '\t', '\n', '(', ')', '.', '-', '+']);
function hasPhone(text: string): boolean {
  let digits = 0;
  for (const ch of text) {
    if (ch >= '0' && ch <= '9') {
      digits += 1;
      if (digits >= 7) return true;
    } else if (!PHONE_SEPARATORS.has(ch)) {
      digits = 0;
    }
  }
  return false;
}

/** Runs every rule and says the first one the text breaks. */
export function checkText(input: string, rules: TextRules = {}): TextCheck {
  const {
    maxLength = 200,
    maxWords = Number.POSITIVE_INFINITY,
    blocklist,
    allowLinks = false,
    allowContact = false,
  } = rules;
  const text = tidyText(input);
  if (!text) return { ok: false, reason: 'empty' };
  if (visibleLength(text) > maxLength) return { ok: false, reason: 'too-long' };
  if (!allowContact && (hasEmail(text) || hasPhone(text))) return { ok: false, reason: 'contact' };
  if (!allowLinks && LINK.test(text)) return { ok: false, reason: 'link' };
  if (blocklist && blocklist.length > 0 && isBlocked(text, blocklist)) return { ok: false, reason: 'blocked' };
  if (wordsOf(text).length > maxWords) return { ok: false, reason: 'too-many-words' };
  return { ok: true, text };
}

/**
 * True when any whole word, or run of words, of `text` is on the list.
 * Letters spelled out with spaces ("b a d") fold back into a word anywhere in
 * the text. Other splits ("ba d") are caught only when they are the whole
 * text, so a moderation queue still matters for open text.
 */
export function isBlocked(text: string, blocklist: readonly string[]): boolean {
  const hay = ` ${foldText(text)} `;
  const squeezed = ` ${hay.replace(/\s+/g, '')} `;
  for (const raw of blocklist) {
    const needle = foldText(raw);
    if (!needle) continue;
    if (hay.includes(` ${needle} `)) return true;
    // The whole text is the word with its spaces taken out ("ba d").
    if (!needle.includes(' ') && squeezed === ` ${needle} `) return true;
  }
  return false;
}

/**
 * @interlace/ui — text-safety-model
 *
 * The checks a short piece of typed text passes before a room shows it on a
 * shared screen: a word for a word cloud, a question for a Q&A board, a line
 * for an open wall. Pure, so the phone that sends it and the server that
 * receives it run the same rules and agree on the reason.
 *
 * ## What it checks, in order
 *
 *   1. empty            nothing left after trimming
 *   2. too-long         more than `maxLength` characters (counted as the reader sees them)
 *   3. contact          an email address or a phone number
 *   4. link             a URL or a bare domain
 *   5. blocked          a word on the consumer's `blocklist`
 *   6. too-many-words   more than `maxWords` words
 *
 * `blocked` comes before the word count, so "b a d" is refused for what it
 * says, not for having three words.
 *
 * Interlace ships no word list of its own: what is unwelcome depends on the
 * room, its language and its audience, so the consumer passes one. Matching
 * runs on `foldText`, which lowercases, strips accents and marks, folds the
 * common letter swaps (0→o, 1→i, 3→e, 4→a, 5→s, 7→t, @→a, $→s) and joins
 * letters spelled out with spaces or dots ("b a d" → "bad"), so the usual
 * dodges do not get through. Whole words only: a blocked word inside a
 * longer, innocent word is not a match.
 *
 * A filter is one layer, never the only one. Rooms that show typed text to
 * a crowd should also hold it for review (see `question-board-model`).
 */
